11	export async function editEvent(
12	  eventId: string,
13	  slug: string,
14	  data: EventBaseRequestDTO
15	): Promise<EditEventResult> {
16	  // 1. Resolve the event by slug and verify the caller-provided id matches.
17	  // This prevents a mismatch where a malicious client passes a slug they own
18	  // alongside an different eventId.
19	  const [currentUser, event] = await Promise.all([
20	    getCurrentUser(),
21	    fetchEventBySlug(slug),
22	  ]);
23	
24	  if (!event) {
25	    return { success: false, error: "Event not found" };
26	  }
27	
28	  if (event.id !== eventId) {
29	    return {
30	      success: false,
31	      error: "Unauthorized: only the event creator can edit this event",
32	    };
33	  }
34	
35	  // Require both IDs to be defined and match. A missing creator on a legacy
36	  // event must not match a logged-out user (undefined === undefined).
37	  const isCreator = Boolean(
38	    currentUser?.id &&
39	      event.owner?.id &&
40	      currentUser.id === event.owner.id,
41	  );
42	  if (!isCreator) {
43	    return {
44	      success: false,
45	      error: "Unauthorized: only the event creator can edit this event",
46	    };
47	  }
48	
49	  // 2. Update the event in your backend using the resolved event id.
50	  // `indexed` is required by the backend's UpdateEventRequestDTO but not part
51	  // of the client-facing form data — add it server-side so the client can't
52	  // accidentally (or maliciously) set it to false.
53	  const updatePayload: EventUpdateRequestDTO = { ...data, indexed: true };
54	  const updatedEvent = await updateEventById(event.id, updatePayload);
55	
56	  // 2. Immediately expire cache tags for event lists and the specific event
57	  // This ensures read-your-own-writes: the updated event appears immediately
58	  updateTag(eventsTag);
59	  // If slug changed, also expire the old event tag
60	  if (updatedEvent.slug !== slug) {
61	    updateTag(eventTag(slug));
62	    deleteEventDetailCache(slug);
63	  }
64	  updateTag(eventTag(updatedEvent.slug));
65	  // Clear the in-memory keyed cache so the internal API route does not serve
66	  // stale data on the next GET (the 30-min TTL would otherwise keep the
67	  // pre-edit event for up to 30 minutes, even after updateTag/refresh).
68	  deleteEventDetailCache(updatedEvent.slug);
69	  // Revalidate the HTML page for all locales so the user sees changes on
70	  // both the old and new slug (if the slug changed from the title update).
71	  try {
72	    for (const locale of SUPPORTED_LOCALES) {
73	      const prefix = locale === DEFAULT_LOCALE ? "" : `/${locale}`;
74	      revalidatePath(`${prefix}/e/${updatedEvent.slug}`);
75	      if (updatedEvent.slug !== slug) {
76	        revalidatePath(`${prefix}/e/${slug}`);
77	      }
78	    }
79	  } catch {
80	    // revalidatePath is a no-op outside of a render context in some environments
81	  }
82	  // Refresh the current request to reflect changes
